{"cards": [{"node_code": "N_7bf4e879d0d12cb2", "definition": "指道路工程施工过程中的管理活动与第三方监理工作，涵盖进度、质量、安全、成本控制，以及监理规划、实施细则、旁站监督与验收程序。", "boundary": "本节点聚焦于“管理”与“监督”职能，而非具体技术操作。边界在于区分“管理/监理”与“施工组织”（侧重内部计划与流程安排）、“施工技术”（侧重具体工艺方法）。若内容涉及施工单位的内部质量管理体系，归入本节点；若涉及监理单位的独立监督行为，亦归入本节点。", "includes": ["道路工程施工进度、质量、安全、成本及合同管理", "工程监理规划、实施细则、旁站、巡视及验收程序", "施工现场的协调、沟通及信息管理"], "excludes": ["具体的路基路面施工工艺与技术参数", "施工机械的操作与维护技术", "施工单位的内部生产计划编制细节"], "sibling_distinctions": [{"other_code": "N_0c3719dc6019332f", "rule": "区分依据为职能主体与内容：本节点侧重管理控制与外部监理监督；施工组织节点侧重施工单位内部的计划、流程与资源配置安排。"}, {"other_code": "N_d74a406398ca456a", "rule": "区分依据为内容性质：本节点侧重管理流程与监督标准；施工技术节点侧重具体的工程做法、工艺参数与技术规范。"}], "cross_boundary_rule": "若内容涉及施工过程中的质量事故处理，侧重管理流程与责任认定归本节点，侧重技术修复方案归施工技术节点。"}, {"node_code": "N_0c3719dc6019332f", "definition": "指道路工程施工前的计划与施工过程中的组织安排，涵盖施工部署、进度计划编制、施工方法选择、资源配置及现场平面布置。", "boundary": "本节点聚焦于“组织”与“计划”层面，即如何安排施工活动。边界在于区分“施工组织”与“施工技术”（侧重具体怎么做）、“施工管理”（侧重控制与监督）。若内容涉及具体的施工工艺流程，归入施工技术；若涉及施工顺序、工期安排、人员机械调配，归入本节点。", "includes": ["道路工程施工部署、施工顺序与进度计划编制", "施工方法选择、劳动力与材料机械资源配置", "施工现场平面布置、临时设施规划及施工流程设计"], "excludes": ["具体的路基路面施工工法与技术细节", "施工机械的性能参数与操作规范", "工程监理的监督程序与管理标准"], "sibling_distinctions": [{"other_code": "N_7bf4e879d0d12cb2", "rule": "区分依据为职能主体与内容：本节点侧重施工单位内部的计划与组织安排；施工管理与监理节点侧重管理控制与外部监理监督。"}, {"other_code": "N_d74a406398ca456a", "rule": "区分依据为内容性质：本节点侧重施工活动的安排与流程设计；施工技术节点侧重具体的工程做法、工艺参数与技术规范。"}], "cross_boundary_rule": "若内容涉及施工方案的比选，侧重技术可行性分析归施工技术，侧重工期与成本比较及最终组织安排归本节点。"}, {"node_code": "N_938513b1c63c9e28", "definition": "指道路工程施工中使用的各类机械设备，涵盖土方、路面、桥梁等施工机械的选型、性能参数、操作规范、维护保养及施工应用。", "boundary": "本节点聚焦于“机械与设备”本身及其在施工中的应用。边界在于区分“机械”与“施工技术”（侧重工艺方法，机械是工具）、“机械”与“施工组织”（侧重计划安排）。若内容涉及机械的选型计算、操作技巧、日常保养，归入本节点；若涉及机械在特定工艺中的配合使用，可关联施工技术，但主挂载本节点。", "includes": ["道路施工机械（如挖掘机、压路机、摊铺机）的选型与性能参数", "施工机械的操作规范、维护保养及故障排除", "施工设备在路基、路面、桥涵工程中的具体应用"], "excludes": ["道路建筑材料的生产设备（归入材料节点）", "施工机械的制造原理与机械设计", "施工组织的进度计划与资源配置安排"], "sibling_distinctions": [{"other_code": "N_d74a406398ca456a", "rule": "区分依据为对象属性：本节点侧重机械设备的性能、操作与维护；施工技术节点侧重利用机械完成工程的具体工艺与流程。"}, {"other_code": "N_0c3719dc6019332f", "rule": "区分依据为内容性质：本节点侧重机械设备的实体与技术特性；施工组织节点侧重机械设备的数量配置与调度计划。"}], "cross_boundary_rule": "若内容涉及施工机械与工艺的匹配，侧重机械选型与参数归本节点，侧重工艺步骤与质量控制归施工技术节点。"}]}
